import builtins
FPS=24.0
def setkeys(parm, keys):
    parm.deleteAllKeyframes()
    n=len(keys)
    for i,(f,v,s) in enumerate(keys):
        if s is None:
            if 0<i<n-1: s=(keys[i+1][1]-keys[i-1][1])/((keys[i+1][0]-keys[i-1][0])/FPS)
            elif i==0 and n>1: s=(keys[1][1]-v)/((keys[1][0]-f)/FPS)
            elif n>1: s=(v-keys[i-1][1])/((f-keys[i-1][0])/FPS)
            else: s=0
        gin=(f-keys[i-1][0])/FPS/3.0 if i>0 else (keys[1][0]-f)/FPS/3.0 if n>1 else 0.1
        gout=(keys[i+1][0]-f)/FPS/3.0 if i<n-1 else gin
        k=hou.Keyframe(); k.setFrame(f); k.setValue(v); k.setSlope(s); k.setInSlope(s)
        k.setAccel(gout); k.setInAccel(gin)
        k.setExpression("bezier()", hou.exprLanguage.Hscript)
        parm.setKeyframe(k)
builtins._setkeys=setkeys
